{
  "findings": [
    {
      "title": "Inconsistent document version dates: Amendment 2 is listed twice with different dates",
      "page": 1,
      "quote": "Amendment 2 03 June 2020\nSuperseding 29 June 2020\nAmendment 2",
      "severity": "major"
    },
    {
      "title": "Protocol version date on title page does not match investigator's agreement date",
      "page": 1,
      "quote": "Protocol Version Date:\nDocument Version Date\nOriginal 19 November 2019\nAmendment 1 21 January 2020\nAmendment 2 03 June 2020\nSuperseding 29 June 2020\nAmendment 2\nAmendment 3 15 February 2021\nAmendment 4 06 January 2022",
      "severity": "minor"
    },
    {
      "title": "Investigator's agreement references a protocol date that is not the latest version",
      "page": 3,
      "quote": "dated 06 January 2022",
      "severity": "minor"
    },
    {
      "title": "Table of contents lists sections that are not present in the excerpt (e.g., sections 8.2.7.1 onward missing content)",
      "page": 7,
      "quote": "8.2.7.1 Biomarker Assessment to Determine\nEligibility (KRAS G12C): Tumor Tissue .................. 96\n8.2.7.2 Central KRAS p.G12C Laboratory\nMethods Summary .................................................. 98\n98\n99\n99\n8.2.8 Medical Resource Utilization and Health Economics ............... 100",
      "severity": "major"
    },
    {
      "title": "Inconsistent numbering in table of contents: page numbers 98, 99, 99 are listed without section titles",
      "page": 7,
      "quote": "98\n99\n99",
      "severity": "minor"
    },
    {
      "title": "Primary endpoint PFS definition lacks a time point for analysis; no explicit primary analysis time is given in the synopsis",
      "page": 11,
      "quote": "PFS - defined as time from randomization until disease progression or death from any cause, whichever occurs first for all subjects.",
      "severity": "minor"
    },
    {
      "title": "Key secondary endpoint ORR definition is incomplete: 'Objective response (CR + PR)' but no explicit time window for response assessment is provided in the synopsis",
      "page": 11,
      "quote": "Objective response (complete response [CR] + partial response [PR]), assessed per RECIST v1.1.",
      "severity": "minor"
    },
    {
      "title": "PRO endpoint description is confusing: 'dyspnea domain from QLQ-C30 and QLQ-LC13' but QLQ-C30 does not have a dyspnea domain; it is in QLQ-LC13",
      "page": 11,
      "quote": "Dyspnea as measured by a 4-item dyspnea domain from QLQ-C30 and QLQ-LC13",
      "severity": "major"
    },
    {
      "title": "Inconsistent use of 'Key Secondary' vs 'Secondary' in objectives/endpoints table",
      "page": 11,
      "quote": "Key Secondary\n• To compare the efficacy of\nAMG 510 versus docetaxel as\nassessed by:\n• Overall Survival (OS)\n• Objective response rate\n(ORR)",
      "severity": "minor"
    },
    {
      "title": "Secondary estimand for OS says 'OS will be estimated regardless of crossover' but crossover is not defined in the synopsis; cross-reference to section 8.1.8 is missing",
      "page": 12,
      "quote": "OS will be estimated regardless of crossover.",
      "severity": "minor"
    },
    {
      "title": "Secondary estimand for PRO lists 'Change from baseline to Week 12' but no statistical analysis method is described in the synopsis",
      "page": 12,
      "quote": "Change from baseline to Week 12",
      "severity": "minor"
    },
    {
      "title": "Sample size and randomization ratio are not stated in the synopsis (section 1.1) despite being essential protocol information",
      "page": 10,
      "quote": "1.1 Synopsis",
      "severity": "major"
    },
    {
      "title": "No inclusion/exclusion criteria are provided in the synopsis; they are only referenced to section 5",
      "page": 10,
      "quote": "1.1 Synopsis",
      "severity": "major"
    },
    {
      "title": "No statistical hypotheses or sample size determination are included in the synopsis; they are only in section 9",
      "page": 10,
      "quote": "1.1 Synopsis",
      "severity": "major"
    }
  ]
}
